// GENERATED by tools/make_office_libs.py from the POS app's invoice.js. Do not edit by hand.
// The key comes from the Netlify setting ANTHROPIC_API_KEY.
// Beer Depot POS: reads a photo of a paper invoice with Claude and returns the lines as data.
// Runs in the Mac app's main process so the API key never reaches a web page. The key is saved on this computer only,
// in <user data>/anthropic-key.txt, and is never part of backups or sent anywhere except to Anthropic's API.

const PROMPT = `You read photos of paper distributor invoices for a beer, wine and liquor store. Return ONLY one JSON object, no other text:
{"supplier":"","invoiceNumber":"","invoiceDate":"YYYY-MM-DD","deliveryFee":0,"invoiceTotal":0,"lines":[{"itemCode":"","upc":"","description":"","cases":0,"unitsPerCase":0,"freeUnits":0,"lineTotal":0,"stdName":""}],"notes":""}
Rules:
- One entry per product line, in the order printed. Copy numbers exactly; use 0 or "" when something is not printed. Never guess a UPC or item code.
- cases = quantity received (the cases shipped column). unitsPerCase = sellable packs in one case (a case of 4 six-packs is 4; a case of 24 cans sold singly is 24). If it is not printed, estimate from the description and say so in notes.
- lineTotal = the extended NET amount for that line after any discount, in dollars. deliveryFee = any delivery, freight or fuel charge in dollars (never as a product line). Deposits and taxes that are separate lines go in notes, not lines.
- NEVER use apostrophes in any name: write SEAGRAMS, not SEAGRAM'S (drop the apostrophe, no space).
- stdName = the product name in this format: ALL CAPS, BRAND + VARIETY + SIZE/PACKAGE, ending in CAN or BOTTLE (box wine ends in BOX). Examples: MILLER 64 EXTRA LIGHT 12PK BOTTLE; MODELO ESPECIAL 16OZ 4PK CAN. Good Boy products keep the Good Boy brand but have no can size. Keep Spotted Cow as printed.
- Fees: deliveryFee = any delivery, freight, fuel or SERVICE fee line (it is never a product line, even when it has an item number).
- Ignore informational rows: "Subbed For" notes, out-of-stock notices, profit-and-loss tables, totals, tax summaries and gallonage. A product with 0 shipped gets cases 0.
- Always answer with the JSON object, even if the page is titled "NOT A FINAL INVOICE", is a pick sheet, driver copy or a long narrow register-tape strip. Read it exactly like an invoice. Never reply with prose.
- If a line has both QTY and UNITS columns (Beechwood style), cases = QTY and unitsPerCase = UNITS divided by QTY (for example QTY 4 UNITS 16 means 4 per case). Skip lines with QTY 0 (out of stock, not delivered).
- Column hints: use the NET extended amount (after unit discounts/allowances) as lineTotal. If there is a "Pack Size" column, unitsPerCase is that number. unitsPerCase is the number of pieces/bottles in one case exactly as printed (the Pieces or BPC column, for example 120 for a case of 50ML bottles). Never divide it by a "10 PACK" or similar in the description; the store sells and counts single pieces.
- Barcodes printed with one digit on each side: the UPC is the left digit + the number printed below the bars + the right digit. Only fill upc when you can read all of it.
- For items that are not beer, wine or liquor (snacks, candy, tobacco, nicotine, frozen food) stdName is just the printed name in ALL CAPS with the size, with no CAN or BOTTLE. Drop vintage years from wine names (BONTERRA CABERNET SAUVIGNON 750ML BOTTLE). PET means a plastic bottle: BOTTLE.
- Some invoices have several pages and each photo is one page. Fill invoiceTotal only if this page prints the total; otherwise 0.
- invoiceTotal = the grand total printed on the invoice. If any part of the photo is cut off or unreadable, say which part in notes.`;

export function makeInvoice(o) {
  const doFetch = o.fetch || fetch;
  const api = o.api || 'https://api.anthropic.com';
  const cheap = o.cheapModel || 'claude-haiku-5-5', strong = o.strongModel || 'claude-sonnet-5-5';
  const key = () => ((typeof process !== 'undefined' && process.env && process.env.ANTHROPIC_API_KEY) || '').trim();
  async function call(model, b64, mediaType, extra) {
    const r = await doFetch(api + '/v1/messages', { method: 'POST', headers: { 'x-api-key': key(), 'anthropic-version': '2023-06-01', 'content-type': 'application/json' },
      body: JSON.stringify({ model, max_tokens: 16000, messages: [{ role: 'user', content: [{ type: 'image', source: { type: 'base64', media_type: mediaType, data: b64 } }, { type: 'text', text: PROMPT + (extra ? '\n' + String(extra).slice(0, 8000) : '') }] }] }) });
    if (!r.ok) { let m = ''; try { m = (await r.json()).error.message; } catch (e) { /* none */ } const e = new Error(r.status === 401 ? 'Anthropic refused the key (401). Check ANTHROPIC_API_KEY in Netlify.' : r.status === 429 ? 'Anthropic says slow down or the spending limit was reached (429).' : 'Anthropic answered ' + r.status + (m ? ': ' + m : '')); e.status = r.status; throw e; }
    const j = await r.json(); const text = (j.content || []).map((c) => c.text || '').join('');
    const a = text.indexOf('{'), z = text.lastIndexOf('}'); if (a < 0 || z < a) throw new Error('The reply was not readable data. It said: ' + text.replace(/\s+/g, ' ').slice(0, 160) + (j.stop_reason === 'max_tokens' ? ' (the invoice was too long for one reply)' : ''));
    const d = JSON.parse(text.slice(a, z + 1)); d.model = model; d.usage = j.usage || null; return d;
  }
  const sum = (d) => (d.lines || []).reduce((t, l) => t + (Number(l.lineTotal) || 0), 0) + (Number(d.deliveryFee) || 0) - (Array.isArray(d.returns) ? d.returns : []).reduce((t, x) => t + (Number(x.amount) || 0), 0);
  const ok = (d) => { const t = Number(d.invoiceTotal) || 0; return !t || Math.abs(sum(d) - t) <= Math.max(0.5, t * 0.01); };
  return {
    info() { return { hasKey: !!key(), cheap, strong }; },
    setKey() { return this.info(); },
    // Tries the cheap model first. Only if its lines do not add up to the invoice total (or it fails to read) does it try the stronger one, once.
    async read(b64, mediaType, extra) {
      if (!key()) throw new Error('The Anthropic key is not set up in Netlify yet (ANTHROPIC_API_KEY).');
      if (!b64 || b64.length > 7 * 1024 * 1024) throw new Error('That photo is too large. Try a smaller photo.');
      let d, firstErr = null;
      try { d = await call(cheap, b64, mediaType || 'image/jpeg', extra); } catch (e) { if (e.status === 401 || e.status === 429) throw e; firstErr = e; }
      if (d && ok(d)) { d.checked = true; d.escalated = false; return d; }
      let d2 = null; try { d2 = await call(strong, b64, mediaType || 'image/jpeg', extra); } catch (e) { if (!d) throw firstErr || e; }
      const best = d2 && (!d || ok(d2) || !ok(d)) ? d2 : d; best.checked = ok(best); best.escalated = !!d2; return best;
    }
  };
}

